        uint16 beforeTotalFee = beforeFee.reward + beforeFee.marketing + beforeFee.burn;
        console.log("Pre-trigger total fee:", beforeTotalFee);
        console.log("Pre-trigger reward fee:", beforeFee.reward);
        console.log("Pre-trigger marketing fee:", beforeFee.marketing);
        console.log("Pre-trigger burn fee:", beforeFee.burn);

        console.log("--- Trigger setBuyFees ---");
        // Attempt to set fees to 26% (10000 = 100% basis points)
        uint16 rewardFee = 1300; // 13%
        uint16 marketingFee = 1300; // 13%
        uint16 burnFee = 0;

        // Owner successfully sets fees beyond 25% limit
        vm.startPrank(owner);
        token.setBuyFees(rewardFee, marketingFee, burnFee);
        vm.stopPrank();

        // After trigger: Query new fee state
        console.log("--- AFTER-Trigger FeeState ---");
        ShibaElonVerse.BuyFee memory afterFee = token.buyFee();
        uint16 afterTotalFee = afterFee.reward + afterFee.marketing + afterFee.burn;
        console.log("Post-trigger total fee:", afterTotalFee);
        console.log("Post-trigger reward fee:", afterFee.reward);
        console.log("Post-trigger marketing fee:", afterFee.marketing);
        console.log("Post-trigger burn fee:", afterFee.burn);

        // Vulnerability verification
        if (afterTotalFee > 2500) {
            console.log("Vulnerability Exists: setBuyFees allows exceeding 25%% limit (actual: %d basis points)", afterTotalFee);
        } else {
            console.log("Vulnerability not Exist: Fees capped at 25%% (actual: %d basis points)", afterTotalFee);
        }
    }
}
```

**Key modifications:**
1. Added fee state queries before and after the vulnerable `setBuyFees()` operation
2. Calculates and compares total fee basis points (reward + marketing + burn)
3. Checks if the post-trigger fee total exceeds 2500 basis points (25%)
4. Outputs structured verification logs showing:
   - Pre-trigger fee state
   - Trigger action (fee modification)
   - Post-trigger fee state
   - Final vulnerability verdict

The final verdict appears as a single concluding line that confirms whether the 25% fee limit can be exceeded through this vulnerability.

